"use client";
import Link from "next/link";
import { useState } from "react";
import { BookOpen, Users, ClipboardList, Star, Plus, Pencil, Trash2, ArrowRight } from "lucide-react";
import { useLearnova } from "@/components/LearnovaProvider";
import { DashboardCard, EmptyState, LoadingCards, PageHeader, StatusBadge } from "@/components/ui";
import { emptyLearning, formatDate, progressFor } from "@/lib/learnova-state";
import { API_URL } from "@/lib/api";
import { assignmentFor, quizFor } from "@/data/learning";

export default function InstructorViews({ view = "overview", allCourses = false }: { view?: "overview" | "courses" | "students" | "assignments" | "quizzes"; allCourses?: boolean }) {
  const { state, user, dispatch } = useLearnova();
  const instructor = user?.role === "instructor" ? user : state.users.find(u => u.id === "instructor-1");
  const courses = allCourses ? state.courses : state.courses.filter(c => c.instructorId === instructor?.id);
  const students = state.users.filter(u => u.role === "student" && courses.some(c => !!state.learning[u.id]?.enrollments[c.id]));
  const [message, setMessage] = useState("");
  const [grading, setGrading] = useState<{ userId: string; courseId: string } | null>(null);
  const [marks, setMarks] = useState(""); const [feedback, setFeedback] = useState("");
  const submissions = courses.flatMap(c => students.flatMap(u => { const submission = state.learning[u.id]?.submissions[c.id]; return submission ? [{ course: c, student: u, submission }] : []; }));
  if (!state.ready) return <LoadingCards />;
  async function remove(id: string) { if (window.confirm("Remove this course and its learning records?")) { if (!(await dispatch({ type: "delete-course", id })).ok) return; setMessage("Course removed."); } }
  const courseTable = () => courses.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Course</th><th>Category</th><th>Level</th><th>Lessons</th><th>Rating</th><th>Actions</th></tr></thead><tbody>{courses.map(c => <tr key={c.id}><td className="font-semibold">{c.title}</td><td>{c.category}</td><td>{c.level}</td><td>{c.lessons.length}</td><td>{c.rating.toFixed(1)}</td><td><div className="flex items-center gap-3"><Link className="text-blue-400" href={`/courses/${c.id}`} aria-label={`View ${c.title}`}>View</Link><Link className="inline-flex items-center gap-1 text-blue-400" href={`/instructor-dashboard/courses/${c.id}/edit`} aria-label={`Edit ${c.title}`}><Pencil size={15} />Edit</Link><button className="text-red-500" aria-label={`Delete ${c.title}`} onClick={() => remove(c.id)}><Trash2 size={17} /></button></div></td></tr>)}</tbody></table></div> : <EmptyState title="Share your knowledge" description="Create your first course and add lessons for your learners." href="/instructor-dashboard/courses/create" action="Create Course" />;
  if (view === "courses") return <><PageHeader title={allCourses ? "Manage Courses" : "My Courses"} description="Create, refine, and manage your course content." action={<Link className="btn-primary" href="/instructor-dashboard/courses/create"><Plus size={17} />Create Course</Link>} />{message && <p className="notice mb-5" role="status">{message}</p>}{courseTable()}</>;
  if (view === "students") return <><PageHeader title="Students" description="See who is learning in your courses and how they are progressing." />{students.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Student</th><th>Email</th><th>Course</th><th>Progress</th><th>Joined</th></tr></thead><tbody>{students.flatMap(u => courses.filter(c => state.learning[u.id]?.enrollments[c.id]).map(c => <tr key={`${u.id}-${c.id}`}><td className="font-semibold">{u.name}</td><td>{u.email}</td><td>{c.title}</td><td>{progressFor(c, state.learning[u.id] ?? emptyLearning())}%</td><td className="whitespace-nowrap">{formatDate(u.joined)}</td></tr>))}</tbody></table></div> : <EmptyState description="Enrolled students will appear here." />}</>;
  if (view === "quizzes") return <><PageHeader title="Quizzes" description="Create knowledge checks and review your students' results." /><div className="grid gap-5 md:grid-cols-2">{courses.map(c => <div className="panel p-6" key={c.id}><h2 className="section-title">{c.title}</h2><p className="mt-3 text-sm text-slate-400">{quizFor(c).length} questions · Pass mark: 70%</p><div className="mt-5 flex flex-wrap gap-3"><Link className="btn-primary" href={`/instructor-dashboard/courses/${c.id}/quiz`}>Edit Quiz</Link><Link className="btn-secondary" href={`/courses/${c.id}/quiz`}>Preview</Link></div><ul className="mt-5 space-y-3">{students.filter(u => state.learning[u.id]?.quizzes[c.id]).map(u => <li key={u.id} className="flex justify-between gap-3 text-sm"><span>{u.name}</span><StatusBadge>{state.learning[u.id].quizzes[c.id].score}%</StatusBadge></li>)}</ul></div>)}</div>{!courses.length && <EmptyState description="Create a course before adding a quiz." href="/instructor-dashboard/courses/create" action="Create Course" />}</>;
  if (view === "assignments") return <><PageHeader title="Assignments" description="Set projects, review submissions, and give constructive feedback." /><div className="mb-7 grid gap-5 md:grid-cols-2">{courses.map(c => <div className="panel p-5" key={c.id}><h2 className="font-bold">{assignmentFor(c).title}</h2><p className="mt-2 text-xs text-slate-400">Due {formatDate(assignmentFor(c).due)}</p><div className="mt-4 flex gap-3"><Link className="text-sm font-semibold text-blue-400" href={`/instructor-dashboard/courses/${c.id}/assignment`}>Edit Assignment</Link><Link className="text-sm font-semibold text-blue-400" href={`/courses/${c.id}/assignment`}>Preview</Link></div></div>)}</div><h2 className="section-title mb-5">Student Submissions</h2>{submissions.length ? <div className="space-y-5">{submissions.map(({ course, student, submission }) => <div className="panel p-6" key={`${course.id}-${student.id}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-bold">{student.name} · {course.title}</h3><p className="mt-2 text-xs text-slate-400">{formatDate(submission.date)}{submission.fileName ? <> <a href={`${API_URL}/courses/${course.id}/submissions/${student.id}/attachment`}>{submission.fileName}</a></> : ""}</p></div><StatusBadge tone={submission.status === "Graded" ? "green" : "blue"}>{submission.status}</StatusBadge></div><p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-slate-300">{submission.text}</p>{submission.marks !== undefined && <p className="mt-3 text-sm font-semibold">Marks: {submission.marks}/100 · {submission.feedback}</p>}<button className="btn-secondary mt-5" onClick={() => { setGrading({ userId: student.id, courseId: course.id }); setMarks(String(submission.marks ?? "")); setFeedback(submission.feedback ?? ""); }}>Grade Submission</button></div>)}</div> : <EmptyState description="Submitted projects will appear here for review." />}{grading && <form className="panel mt-7 space-y-4 p-6" onSubmit={async e => { e.preventDefault(); const value = Number(marks); if (marks.trim() === "" || !Number.isFinite(value) || value < 0 || value > 100 || !feedback.trim()) { setMessage("Enter marks from 0 to 100 and feedback."); return; } if (!(await dispatch({ type: "grade", ...grading, marks: value, feedback: feedback.trim() })).ok) return; setGrading(null); setMessage("Grade saved. It is now visible in the student's assignments."); }}><h3 className="section-title">Grade Submission</h3><label className="block"><span className="field-label">Marks out of 100</span><input className="field" type="number" min="0" max="100" value={marks} onChange={e => setMarks(e.target.value)} required /></label><label className="block"><span className="field-label">Feedback</span><textarea className="field" value={feedback} onChange={e => setFeedback(e.target.value)} required /></label><div className="flex gap-3"><button className="btn-primary">Save Grade</button><button type="button" className="btn-secondary" onClick={() => setGrading(null)}>Cancel</button></div></form>}{message && <p className="notice mt-5" role="status">{message}</p>}</>;
  const average = courses.length ? (courses.reduce((sum, c) => sum + c.rating, 0) / courses.length).toFixed(1) : "—";
  return <><PageHeader art="instructor" title={`Welcome back, ${instructor?.name ?? "Instructor"}`} eyebrow="Teach with purpose" description="Keep your courses moving and help every learner take the next step." action={<Link className="btn-primary" href="/instructor-dashboard/courses/create"><Plus size={17} />Create Course</Link>} /><div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><DashboardCard label="Total Courses" value={courses.length} icon={BookOpen} /><DashboardCard label="Total Students" value={students.length} icon={Users} /><DashboardCard label="Total Assignments" value={courses.length} icon={ClipboardList} /><DashboardCard label="Average Rating" value={average} icon={Star} /></div><div className="mb-5 flex justify-between"><h2 className="section-title">My Courses</h2><Link href="/instructor-dashboard/courses" className="text-sm font-semibold text-blue-400">View all</Link></div>{courseTable()}<div className="mt-7 grid gap-6 xl:grid-cols-2"><section className="panel p-6"><h2 className="section-title">Recent Students</h2>{students.slice(-4).map(u => <div className="mt-5 flex items-center gap-3" key={u.id}><span className="avatar">{u.name.split(" ").map(n => n[0]).join("")}</span><div><p className="text-sm font-semibold">{u.name}</p><p className="mt-1 text-xs text-slate-400">{u.email}</p></div></div>)}{!students.length && <p className="mt-5 text-sm text-slate-400">Your first learners will appear here.</p>}</section><section className="panel p-6"><h2 className="section-title">Recent Activities</h2>{state.activity.slice(0, 5).map((item, i) => <p key={i} className="mt-4 flex items-start gap-3 text-sm leading-6 text-slate-400"><ArrowRight size={15} className="mt-1 shrink-0 text-blue-500" />{item}</p>)}</section></div></>;
}
